            totalLimit?: number | null;
            /** @description 商品级限购额度，只服务虚拟道具「一个账号一件」这一套，按账号判定；与限时抢购的本场额度 campaignLimit（按实名、按场配置）是两条独立规则，不合并、不互相复制。不限购时为 null。 */
